function New-JArray([object[]]$Items = @()) { $a = [System.Text.Json.Nodes.JsonArray]::new(); foreach ($i in $Items) { [void]$a.Add($i) }; return $a }
function New-JObject([hashtable]$Values) { $o = [System.Text.Json.Nodes.JsonObject]::new(); foreach ($k in $Values.Keys) { [void]$o.Add($k, $Values[$k]) }; return $o }
function Get-Sha([string]$Path) { return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant() }
function New-Identity([string]$Path, [string]$Token) { return New-JObject ([ordered]@{path_token=[System.Text.Json.Nodes.JsonValue]::Create($Token);byte_count=[System.Text.Json.Nodes.JsonValue]::Create([int64](Get-Item -LiteralPath $Path).Length);sha256=[System.Text.Json.Nodes.JsonValue]::Create((Get-Sha $Path))}) }
function New-Artifact([string]$Path, [string]$Token) { if (Test-Path -LiteralPath $Path) { return New-JObject ([ordered]@{state=[System.Text.Json.Nodes.JsonValue]::Create('PRESENT');path_token=[System.Text.Json.Nodes.JsonValue]::Create($Token);byte_count=[System.Text.Json.Nodes.JsonValue]::Create([int64](Get-Item -LiteralPath $Path).Length);sha256=[System.Text.Json.Nodes.JsonValue]::Create((Get-Sha $Path))}) }; return New-JObject ([ordered]@{state=[System.Text.Json.Nodes.JsonValue]::Create('ABSENT');path_token=[System.Text.Json.Nodes.JsonValue]::Create($Token);byte_count=[System.Text.Json.Nodes.JsonValue]::Create(0);sha256=[System.Text.Json.Nodes.JsonValue]::Create('ABSENT')}) }
function Get-Schema([string]$Name) { $d=[System.Text.Json.JsonDocument]::Parse([string][System.IO.File]::ReadAllText($SchemaPath)); try { return $d.RootElement.GetProperty('schemas').GetProperty($Name).Clone() } finally { $d.Dispose() } }
function Assert-ClosedReceipt([string]$Path, [string]$SchemaName) {
  $d=[System.Text.Json.JsonDocument]::Parse([string][System.IO.File]::ReadAllText($Path)); try {
    $s=Get-Schema $SchemaName; $actual=@($d.RootElement.EnumerateObject() | ForEach-Object Name | Sort-Object); $expected=@($s.GetProperty('exact_properties').EnumerateArray() | ForEach-Object String | Sort-Object)
    if (($actual -join '|') -cne ($expected -join '|')) { throw "Closed key set mismatch in $Path" }
    foreach ($p in $s.GetProperty('property_token_kinds').EnumerateObject()) { $actualKind=$d.RootElement.GetProperty($p.Name).ValueKind.ToString(); if ($actualKind -cne $p.Value.GetString()) { throw "Token kind mismatch at $Path#$($p.Name): $actualKind" } }
    foreach ($p in $s.GetProperty('array_properties').EnumerateArray()) { $e=$d.RootElement.GetProperty($p.GetString()); if ($e.ValueKind -ne [System.Text.Json.JsonValueKind]::Array) { throw "Array token proof failed at $Path#$($p.GetString())" }; [void]$e.GetArrayLength() }
  } finally { $d.Dispose() }
}
function Write-DirectClosed([string]$Path, [string]$SchemaName, [System.Text.Json.Nodes.JsonObject]$Root) { [System.IO.File]::WriteAllText($Path, $Root.ToJsonString([System.Text.Json.JsonSerializerOptions]@{WriteIndented=$true}) + "`n", $Utf8NoBom); Assert-ClosedReceipt $Path $SchemaName }
