function Close-DirectManifest([string]$Root,[string]$Phase,[string]$Status) { $m=Join-Path $Root 'manifest.json';$prefix=$Root.TrimEnd('\\')+'\\';$entries=[System.Text.Json.Nodes.JsonArray]::new();$files=@(Get-ChildItem -LiteralPath $Root -File -Recurse -Force | Where-Object { $_.FullName -cne $m } | Sort-Object FullName);foreach($f in $files){[void]$entries.Add((New-JObject ([ordered]@{relative_path=[System.Text.Json.Nodes.JsonValue]::Create($f.FullName.Substring($prefix.Length).Replace('\\','/'));byte_count=[System.Text.Json.Nodes.JsonValue]::Create([int64]$f.Length);sha256=[System.Text.Json.Nodes.JsonValue]::Create((Get-Sha $f.FullName))})))};$root=New-JObject ([ordered]@{schema_version=[System.Text.Json.Nodes.JsonValue]::Create('manifest-v1');phase=[System.Text.Json.Nodes.JsonValue]::Create($Phase);status=[System.Text.Json.Nodes.JsonValue]::Create($Status);self_excluding=[System.Text.Json.Nodes.JsonValue]::Create($true);excluded_relative_path=[System.Text.Json.Nodes.JsonValue]::Create('manifest.json');file_count=[System.Text.Json.Nodes.JsonValue]::Create($entries.Count);files=$entries});Write-DirectClosed $m 'manifest-v1' $root }
